import React, { useState, useEffect, useContext } from 'react';
import Navbar from '../components/Navbar';
import { AuthContext } from '../context/AuthContext';
import { API_URL } from '../config';

const AdminDashboard = () => {
  const { token } = useContext(AuthContext);
  const [summary, setSummary] = useState(null);
  const [messages, setMessages] = useState([]);
  const [courses, setCourses] = useState([]);
  const [selectedCourseId, setSelectedCourseId] = useState(null);
  const [courseToEdit, setCourseToEdit] = useState(null);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const authHeaders = { Authorization: `Bearer ${token}` };

  useEffect(() => {
    fetch(`${API_URL}/payments/admin/summary`, { headers: authHeaders })
      .then(res => res.ok ? res.json() : null)
      .then(setSummary);

    fetch(`${API_URL}/contact/`, { headers: authHeaders })
      .then(res => res.ok ? res.json() : [])
      .then(setMessages);

    fetch(`${API_URL}/courses/`)
      .then(res => res.json())
      .then(data => {
        setCourses(data);
        if (data.length > 0) {
          setSelectedCourseId(data[0].id);
          setCourseToEdit(data[0]);
        }
      });
  }, [token]);

  const handleCourseSelect = (id) => {
    const c = courses.find(c => c.id === parseInt(id));
    setSelectedCourseId(c.id);
    setCourseToEdit(c);
  };

  const addLesson = () => {
    setCourseToEdit({
      ...courseToEdit,
      lessons: [...courseToEdit.lessons, { id: `new-${Date.now()}`, title: '', duration: '00:00', video_url: '' }]
    });
  };

  const updateLesson = (lessonId, field, value) => {
    setCourseToEdit({
      ...courseToEdit,
      lessons: courseToEdit.lessons.map(l => l.id === lessonId ? { ...l, [field]: value } : l)
    });
  };

  const saveCourse = async (status) => {
    setIsSaving(true);
    try {
      await fetch(`${API_URL}/courses/${courseToEdit.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', ...authHeaders },
        body: JSON.stringify({
          title: courseToEdit.title,
          description: courseToEdit.description,
          price: courseToEdit.price,
          is_free: courseToEdit.is_free,
          category: courseToEdit.category,
          status,
        }),
      });
      setSaveSuccess(status);
      setTimeout(() => setSaveSuccess(false), 3000);
    } finally {
      setIsSaving(false);
    }
  };

  const resolveMessage = async (id) => {
    await fetch(`${API_URL}/contact/${id}/resolve`, { method: 'PUT', headers: authHeaders });
    setMessages(messages.map(m => m.id === id ? { ...m, resolved: true } : m));
  };

  if (!courseToEdit) {
    return <div className="min-h-screen bg-[#0A0E1A] text-slate-500 text-sm flex items-center justify-center">Chargement...</div>;
  }

  return (
    <div className="min-h-screen bg-[#0A0E1A] text-slate-200">
      <Navbar />

      <div className="max-w-5xl mx-auto px-6 py-12 space-y-10">

        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 border-b border-slate-800 pb-8">
          <div>
            <span className="text-[11px] font-semibold text-blue-400 tracking-wide uppercase">Console de gestion</span>
            <h1 className="text-2xl font-bold text-white mt-1">Panneau d'administration</h1>
          </div>
          <div className="flex items-center gap-3">
            <span className={`text-[11px] font-bold uppercase tracking-wide px-3 py-1.5 rounded-full ${
              courseToEdit.status === 'published' ? 'bg-emerald-500/10 text-emerald-400' : 'bg-amber-500/10 text-amber-400'
            }`}>
              {courseToEdit.status === 'published' ? 'Publié' : 'Brouillon'}
            </span>
            <button onClick={() => saveCourse('draft')} className="border border-slate-700 hover:border-slate-500 text-slate-300 hover:text-white font-semibold px-5 py-2.5 rounded-lg text-sm transition-colors">
              Enregistrer comme brouillon
            </button>
            <button onClick={() => saveCourse('published')} className="bg-blue-600 hover:bg-blue-500 text-white font-semibold px-6 py-2.5 rounded-lg text-sm transition-colors">
              {isSaving ? 'Déploiement...' : 'Publier'}
            </button>
          </div>
        </div>

        {saveSuccess && (
          <div className="bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 text-sm rounded-lg px-4 py-3">
            {saveSuccess === 'published' ? '✓ Module publié.' : '✓ Brouillon enregistré.'}
          </div>
        )}

        {summary && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
              <p className="text-[11px] uppercase text-slate-500 font-semibold tracking-wide">Chiffre d'affaires total</p>
              <p className="text-xl font-bold mt-2 text-white">{summary.total_revenue.toLocaleString()} FCFA</p>
            </div>
            <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
              <p className="text-[11px] uppercase text-slate-500 font-semibold tracking-wide">Meilleure vente</p>
              <p className="text-sm mt-2 font-bold text-white">{summary.top_course.title || '—'} · {summary.top_course.sales} ventes</p>
            </div>
            <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
              <p className="text-[11px] uppercase text-slate-500 font-semibold tracking-wide">Répartition paiement</p>
              <p className="text-sm mt-2 font-bold text-white">
                {Object.entries(summary.payment_breakdown).map(([k, v]) => `${k.toUpperCase()} ${v}`).join(' · ') || 'Aucune vente'}
              </p>
            </div>
          </div>
        )}

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-sm font-bold text-white">Configuration du module</h3>
            <select
              value={selectedCourseId}
              onChange={(e) => handleCourseSelect(e.target.value)}
              className="bg-slate-950 border border-slate-800 text-white text-xs px-3 py-2 rounded-lg outline-none"
            >
              {courses.map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
            </select>
          </div>
          <input
            type="text" value={courseToEdit.title}
            onChange={(e) => setCourseToEdit({ ...courseToEdit, title: e.target.value })}
            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-3 text-sm text-white outline-none focus:border-blue-500 transition-colors"
          />

          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Programme ({courseToEdit.lessons.length} leçons)</span>
              <button onClick={addLesson} className="text-xs text-blue-400 hover:text-blue-300 font-semibold">+ Ajouter une leçon</button>
            </div>
            {courseToEdit.lessons.map((lesson) => (
              <div key={lesson.id} className="grid md:grid-cols-12 gap-3 items-center bg-slate-950 p-3 rounded-lg border border-slate-800">
                <input className="md:col-span-6 bg-slate-900 border border-slate-800 px-3 py-2 text-xs rounded-lg text-white outline-none focus:border-blue-500" value={lesson.title} onChange={(e) => updateLesson(lesson.id, 'title', e.target.value)} placeholder="Titre de la leçon" />
                <input className="md:col-span-2 bg-slate-900 border border-slate-800 px-3 py-2 text-xs rounded-lg text-white outline-none focus:border-blue-500" value={lesson.duration} onChange={(e) => updateLesson(lesson.id, 'duration', e.target.value)} placeholder="00:00" />
                <input className="md:col-span-4 bg-slate-900 border border-slate-800 px-3 py-2 text-xs rounded-lg text-white outline-none focus:border-blue-500" value={lesson.video_url || ''} onChange={(e) => updateLesson(lesson.id, 'video_url', e.target.value)} placeholder="Lien vidéo" />
              </div>
            ))}
          </div>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden">
          <div className="p-6 border-b border-slate-800"><h3 className="text-sm font-bold text-white">Messages support</h3></div>
          <table className="w-full text-xs text-left">
            <thead className="bg-slate-950 text-slate-500 uppercase">
              <tr><th className="p-4">Utilisateur</th><th className="p-4">Message</th><th className="p-4">Statut</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {messages.map(m => (
                <tr key={m.id}>
                  <td className="p-4 text-slate-300">{m.email}</td>
                  <td className="p-4 text-slate-400">{m.subject}</td>
                  <td className="p-4">
                    {m.resolved ? (
                      <span className="text-emerald-400 uppercase text-[11px] font-semibold">Traité</span>
                    ) : (
                      <button onClick={() => resolveMessage(m.id)} className="text-blue-400 hover:text-blue-300 font-semibold uppercase text-[11px]">Marquer traité</button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

      </div>
    </div>
  );
};
export default AdminDashboard;
